CREATE VIEW `v_portfolio_summary` AS 
  SELECT 
    o.id AS organization_id,
    (SELECT COUNT(*) FROM policies p WHERE p.organizationId = o.id AND p.status = 'active' AND p.deleted_at IS NULL) AS active_policies_count,
    (SELECT COUNT(*) FROM insureds i WHERE i.organizationId = o.id AND i.deleted_at IS NULL) AS total_insureds_count,
    (SELECT COUNT(*) FROM policy_installments pi WHERE pi.organizationId = o.id AND pi.status = 'paid' AND substr(pi.dueDate, 1, 7) = strftime('%Y-%m', 'now', 'localtime') AND pi.deleted_at IS NULL) AS paid_installments_this_month_count,
    (SELECT COUNT(*) FROM policy_installments pi WHERE pi.organizationId = o.id AND substr(pi.dueDate, 1, 7) = strftime('%Y-%m', 'now', 'localtime') AND pi.deleted_at IS NULL) AS total_installments_this_month_count
  FROM organization o
;--> statement-breakpoint
CREATE VIEW `v_portfolio_companies` AS 
  SELECT 
    p.organizationId AS organization_id,
    p.companyId AS company_id,
    c.name AS company_name,
    c.code AS company_code,
    COUNT(*) AS active_policies_count
  FROM policies p
  JOIN companies c ON c.id = p.companyId
  WHERE p.status = 'active' AND p.deleted_at IS NULL AND c.deleted_at IS NULL
  GROUP BY p.organizationId, p.companyId, c.name, c.code
;--> statement-breakpoint
CREATE VIEW `v_due_installments` AS select "policy_installments"."id", "policy_installments"."organizationId", "policy_installments"."policyId", "policy_installments"."installmentNumber", "policy_installments"."dueDate", "policy_installments"."totalAmount", "policy_installments"."currency", "policy_installments"."status", "policy_installments"."receiptUrl", (SELECT COALESCE(json_extract(a.properties, '$.PATENTE'), json_extract(a.properties, '$.patente'), json_extract(a.properties, '$.dominio'), json_extract(a.properties, '$.plate')) FROM policy_assets pa INNER JOIN assets a ON a.id = pa.assetId AND a.deleted_at IS NULL WHERE pa.policyId = "policies"."id" AND pa.deleted_at IS NULL LIMIT 1) as "plateNumber", "policies"."policyNumber", "policies"."status", "policies"."startDate", "policies"."endDate", "policies"."effectiveEndDate", "policies"."companyId", "companies"."name", "companies"."code", "insureds"."id", "insureds"."fullName", "insureds"."phone", "insureds"."email", "insureds"."cuit" from "policy_installments" inner join "policies" on "policies"."id" = "policy_installments"."policyId" inner join "insureds" on "insureds"."id" = "policies"."insuredId" inner join "companies" on "companies"."id" = "policies"."companyId" where ((("policy_installments"."deleted_at" is null)) and (("policies"."deleted_at" is null)) and (("insureds"."deleted_at" is null)) and (("companies"."deleted_at" is null)));--> statement-breakpoint
CREATE VIEW `v_expiring_policies` AS select "policies"."id", "policies"."organizationId", "policies"."policyNumber", "policies"."status", "policies"."startDate", "policies"."endDate", "policies"."effectiveEndDate", COALESCE("policies"."effectiveEndDate", "policies"."endDate") as "expiration_date", (SELECT COALESCE(json_extract(a.properties, '$.PATENTE'), json_extract(a.properties, '$.patente'), json_extract(a.properties, '$.dominio'), json_extract(a.properties, '$.plate')) FROM policy_assets pa INNER JOIN assets a ON a.id = pa.assetId AND a.deleted_at IS NULL WHERE pa.policyId = "policies"."id" AND pa.deleted_at IS NULL LIMIT 1) as "plateNumber", "policies"."companyId", "companies"."name", "companies"."code", "insureds"."id", "insureds"."fullName", "insureds"."phone", "insureds"."email", "insureds"."cuit" from "policies" inner join "insureds" on "insureds"."id" = "policies"."insuredId" inner join "companies" on "companies"."id" = "policies"."companyId" where ((("policies"."deleted_at" is null)) and (("insureds"."deleted_at" is null)) and (("companies"."deleted_at" is null)));--> statement-breakpoint
CREATE VIEW `v_due_reminders` AS select "reminder_rules"."id" as "ruleId", "reminder_rules"."organizationId" as "organizationId", "reminder_rules"."eventSource" as "eventSource", "reminder_rules"."offsetDays" as "offsetDays", date("policy_installments"."dueDate", printf('%+d days', "reminder_rules"."offsetDays")) as "scheduledDate", "policy_installments"."dueDate" as "targetDate", 'installment' as "entityType", "policy_installments"."id" as "entityId", "policies"."id" as "policyId", "policies"."policyNumber" as "policyNumber", "policies"."status" as "policyStatus", "policies"."startDate" as "policyStartDate", "policies"."endDate" as "policyEndDate", "policies"."effectiveEndDate" as "policyEffectiveEndDate", "companies"."id" as "companyId", "companies"."name" as "companyName", "companies"."code" as "companyCode", "insureds"."id" as "insuredId", "insureds"."fullName" as "insuredFullName", "insureds"."phone" as "insuredPhone", "insureds"."email" as "insuredEmail", "insureds"."cuit" as "insuredCuit", (SELECT COALESCE(json_extract(a.properties, '$.PATENTE'), json_extract(a.properties, '$.patente'), json_extract(a.properties, '$.dominio'), json_extract(a.properties, '$.plate')) FROM policy_assets pa INNER JOIN assets a ON a.id = pa.assetId AND a.deleted_at IS NULL WHERE pa.policyId = "policies"."id" AND pa.deleted_at IS NULL LIMIT 1) as "plateNumber", "policy_installments"."id" as "installmentId", "policy_installments"."installmentNumber" as "installmentNumber", "policy_installments"."totalAmount" as "totalAmount", "policy_installments"."currency" as "currency", "policy_installments"."dueDate" as "dueDate", COALESCE("policies"."effectiveEndDate", "policies"."endDate") as "expirationDate", "policy_installments"."receiptUrl" as "receiptUrl", "reminder_rules"."templateId" as "templateId", COALESCE("message_templates"."name", 'reminder_default') as "templateName", "message_templates"."code" as "templateCode", "message_templates"."body" as "templateBody", COALESCE("communication_consents"."isOptedOut", 0) as "isOptedOut", CASE WHEN COALESCE("communication_consents"."isOptedOut", 0) = 0 AND "insureds"."phone" IS NOT NULL AND trim("insureds"."phone") != '' THEN 1 ELSE 0 END as "canDeliver", CASE WHEN COALESCE("communication_consents"."isOptedOut", 0) = 1 THEN 'opt_out' WHEN "insureds"."phone" IS NULL OR trim("insureds"."phone") = '' THEN 'missing_phone' ELSE NULL END as "skipReason" from "reminder_rules" inner join "policy_installments" on (("policy_installments"."organizationId" = "reminder_rules"."organizationId") and ("policy_installments"."status" <> 'paid') and (("policy_installments"."deleted_at" is null))) inner join "policies" on (("policies"."id" = "policy_installments"."policyId") and (("policies"."deleted_at" is null))) inner join "insureds" on (("insureds"."id" = "policies"."insuredId") and (("insureds"."deleted_at" is null))) inner join "companies" on (("companies"."id" = "policies"."companyId") and (("companies"."deleted_at" is null))) left join "message_templates" on (("message_templates"."id" = "reminder_rules"."templateId") and (("message_templates"."deleted_at" is null))) left join "communication_categories" on (("communication_categories"."code" = 'billing') and (("communication_categories"."deleted_at" is null))) left join "communication_consents" on (("communication_consents"."organizationId" = "reminder_rules"."organizationId") and ("communication_consents"."insuredId" = "insureds"."id") and ("communication_consents"."categoryId" = "communication_categories"."id") and (("communication_consents"."deleted_at" is null))) where (("reminder_rules"."eventSource" = 'installment_due') and ("reminder_rules"."isEnabled" = 1) and (("reminder_rules"."deleted_at" is null))) union all select "reminder_rules"."id" as "ruleId", "reminder_rules"."organizationId" as "organizationId", "reminder_rules"."eventSource" as "eventSource", "reminder_rules"."offsetDays" as "offsetDays", date(COALESCE("policies"."effectiveEndDate", "policies"."endDate"), printf('%+d days', "reminder_rules"."offsetDays")) as "scheduledDate", COALESCE("policies"."effectiveEndDate", "policies"."endDate") as "targetDate", 'policy' as "entityType", "policies"."id" as "entityId", "policies"."id" as "policyId", "policies"."policyNumber" as "policyNumber", "policies"."status" as "policyStatus", "policies"."startDate" as "policyStartDate", "policies"."endDate" as "policyEndDate", "policies"."effectiveEndDate" as "policyEffectiveEndDate", "companies"."id" as "companyId", "companies"."name" as "companyName", "companies"."code" as "companyCode", "insureds"."id" as "insuredId", "insureds"."fullName" as "insuredFullName", "insureds"."phone" as "insuredPhone", "insureds"."email" as "insuredEmail", "insureds"."cuit" as "insuredCuit", (SELECT COALESCE(json_extract(a.properties, '$.PATENTE'), json_extract(a.properties, '$.patente'), json_extract(a.properties, '$.dominio'), json_extract(a.properties, '$.plate')) FROM policy_assets pa INNER JOIN assets a ON a.id = pa.assetId AND a.deleted_at IS NULL WHERE pa.policyId = "policies"."id" AND pa.deleted_at IS NULL LIMIT 1) as "plateNumber", NULL as "installmentId", NULL as "installmentNumber", NULL as "totalAmount", "policies"."currency" as "currency", NULL as "dueDate", COALESCE("policies"."effectiveEndDate", "policies"."endDate") as "expirationDate", NULL as "receiptUrl", "reminder_rules"."templateId" as "templateId", COALESCE("message_templates"."name", 'reminder_default') as "templateName", "message_templates"."code" as "templateCode", "message_templates"."body" as "templateBody", COALESCE("communication_consents"."isOptedOut", 0) as "isOptedOut", CASE WHEN COALESCE("communication_consents"."isOptedOut", 0) = 0 AND "insureds"."phone" IS NOT NULL AND trim("insureds"."phone") != '' THEN 1 ELSE 0 END as "canDeliver", CASE WHEN COALESCE("communication_consents"."isOptedOut", 0) = 1 THEN 'opt_out' WHEN "insureds"."phone" IS NULL OR trim("insureds"."phone") = '' THEN 'missing_phone' ELSE NULL END as "skipReason" from "reminder_rules" inner join "policies" on (("policies"."organizationId" = "reminder_rules"."organizationId") and ("policies"."status" = 'active') and (("policies"."deleted_at" is null))) inner join "insureds" on (("insureds"."id" = "policies"."insuredId") and (("insureds"."deleted_at" is null))) inner join "companies" on (("companies"."id" = "policies"."companyId") and (("companies"."deleted_at" is null))) left join "message_templates" on (("message_templates"."id" = "reminder_rules"."templateId") and (("message_templates"."deleted_at" is null))) left join "communication_categories" on (("communication_categories"."code" = 'renewals') and (("communication_categories"."deleted_at" is null))) left join "communication_consents" on (("communication_consents"."organizationId" = "reminder_rules"."organizationId") and ("communication_consents"."insuredId" = "insureds"."id") and ("communication_consents"."categoryId" = "communication_categories"."id") and (("communication_consents"."deleted_at" is null))) where (("reminder_rules"."eventSource" = 'policy_expiration') and ("reminder_rules"."isEnabled" = 1) and (("reminder_rules"."deleted_at" is null)));--> statement-breakpoint
